import{_ as t,c as i,o as n,ag as a}from"./chunks/framework.nnfp71k2.js";const r="/tutorial/img/spacing-input.png",o="/tutorial/img/add-kerning.png",s="/tutorial/img/edit-kerning.png",p="/tutorial/img/kerning-preview.png",k=JSON.parse('{"title":"Spacing and Kerning","description":"Adjust letter spacing, line height and kerning pairs of a bitmap font in Calligro.","frontmatter":{"description":"Adjust letter spacing, line height and kerning pairs of a bitmap font in Calligro.","head":[["link",{"rel":"canonical","href":"https://calligro.ideasalmanac.com/tutorial/guide/spacing-and-kerning"}],["meta",{"property":"og:url","content":"https://calligro.ideasalmanac.com/tutorial/guide/spacing-and-kerning"}],["meta",{"property":"og:title","content":"Spacing and Kerning | Calligro"}],["meta",{"property":"og:description","content":"Adjust letter spacing, line height and kerning pairs of a bitmap font in Calligro."}],["meta",{"property":"twitter:title","content":"Spacing and Kerning | Calligro"}],["meta",{"property":"twitter:description","content":"Adjust letter spacing, line height and kerning pairs of a bitmap font in Calligro."}]]},"headers":[],"relativePath":"guide/spacing-and-kerning.md","filePath":"guide/spacing-and-kerning.md","lastUpdated":1790617747000}'),c={name:"guide/spacing-and-kerning.md"};function g(l,e,d,h,u,m){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="spacing-and-kerning" tabindex="-1">Spacing and Kerning <a class="header-anchor" href="#spacing-and-kerning" aria-label="Permalink to &quot;Spacing and Kerning&quot;">​</a></h1><p>Font Settings let you adjust additional properties like spacing, line height, and kerning. These can still be changed after the template has been imported.</p><h2 id="spacing-and-line-height" tabindex="-1">Spacing and line height <a class="header-anchor" href="#spacing-and-line-height" aria-label="Permalink to &quot;Spacing and line height&quot;">​</a></h2><p>Horizontal spacing is the space in pixels between characters. If spacing is set to 0, characters are directly next to each other (as defined by the template sizes).</p><p>Line height is the vertical space between lines of text.</p><p><img src="'+r+'" alt="Spacing and line height inputs"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There&#39;s also a vertical spacing input. It&#39;s deprecated since Calligro 2.4.0. Use line height instead.</p></div><h2 id="kerning-pairs" tabindex="-1">Kerning pairs <a class="header-anchor" href="#kerning-pairs" aria-label="Permalink to &quot;Kerning pairs&quot;">​</a></h2><p>Kerning pairs let you define custom spacing between specific character pairs. For example, if you want &quot;a&quot; to be closer to &quot;b&quot; than to &quot;c&quot;, add a kerning pair for &quot;ab&quot; with a negative value. This value sets how much the second character moves relative to the first.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Although kerning pairs are part of the BMFont specification, not all game engines support them. This is often not documented, so you may need to test whether your engine supports kerning. See the <a href="/tutorial/engines/#compatibility">engine compatibility table</a> for known cases.</p></div><p>To add a pair, click the &quot;+&quot; button next to the kerning pairs input. A dialog appears where you can enter the characters and spacing. Click &quot;Add&quot; to save the pair.</p><p>You can enter multiple characters in the first and second character inputs to create multiple pairs at once. For example, entering &quot;ab&quot; in the first input and &quot;cd&quot; in the second creates the pairs &quot;ac&quot;, &quot;ad&quot;, &quot;bc&quot;, and &quot;bd&quot;.</p><p><img src="'+o+'" alt="Add kerning pair dialog"></p><p>You can edit an existing pair by selecting it from the dropdown and adjusting the distance. To remove a pair, press the &quot;-&quot; button next to the dropdown.</p><p><img src="'+s+'" alt="Edit kerning"><img src="'+p+'" alt="Kerning preview"></p>',15)])])}const b=t(c,[["render",g]]);export{k as __pageData,b as default};
